-- Inventory the original B1 MP3 assets without guessing which exercise each file belongs to.
-- The binaries remain public static assets; D1 stores only their metadata and provenance.
-- Explicit exercise mapping can be added later after the original audio-to-exercise manifest is verified.

CREATE TABLE IF NOT EXISTS learning_course_audio_assets (
  asset_path TEXT PRIMARY KEY,
  course_key TEXT NOT NULL,
  unit_number INTEGER NOT NULL CHECK (unit_number > 0),
  file_name TEXT NOT NULL,
  public_url TEXT NOT NULL,
  source_blob_sha TEXT NOT NULL,
  mapping_status TEXT NOT NULL DEFAULT 'unmapped'
    CHECK (mapping_status IN ('unmapped', 'mapped', 'retired')),
  exercise_id TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  CHECK (asset_path LIKE 'public/audio/b1/%'),
  CHECK (public_url LIKE '/audio/b1/%')
);

CREATE INDEX IF NOT EXISTS idx_learning_course_audio_assets_unit
  ON learning_course_audio_assets(course_key, unit_number, mapping_status);

ON CONFLICT(asset_path) DO UPDATE SET
  course_key = excluded.course_key,
  unit_number = excluded.unit_number,
  file_name = excluded.file_name,
  public_url = excluded.public_url,
  source_blob_sha = excluded.source_blob_sha,
  mapping_status = CASE
    WHEN learning_course_audio_assets.mapping_status = 'mapped' THEN 'mapped'
    ELSE 'unmapped'
  END;
